code_example:
int add_one(int x) { return x + 1; }

template <typename F, typename T>
auto apply(F op, T val) {
    return op(val); // Calls the generic callable
}

auto lambda_mult = [](int x){ return x * 2; };

int r1 = apply(add_one, 10);         // F deduced as function pointer
int r2 = apply(lambda_mult, 10);     // F deduced as lambda closure type
double r3 = apply(
    [](auto x){ return x * x; }, 
    5.0);                            // Generic lambda
